-- Fresh NEAR-only schema. All monetary values are exact integer base units.
CREATE TYPE webhook_delivery_status AS ENUM ('pending','delivering','retrying','delivered','failed');

CREATE TABLE organizations (id text PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL, reporting_currency text NOT NULL DEFAULT 'USD', timezone text NOT NULL DEFAULT 'UTC', support_email text, onboarding_completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id text PRIMARY KEY, email text UNIQUE NOT NULL, name text, password_hash text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members (id text UNIQUE NOT NULL, organization_id text NOT NULL REFERENCES organizations(id), user_id text NOT NULL REFERENCES users(id), role text NOT NULL DEFAULT 'member', notifications_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id));
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), organization_id text REFERENCES organizations(id), environment text NOT NULL DEFAULT 'test', token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, ip_hash text, user_agent text, last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_resets (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), email text NOT NULL, role text NOT NULL, token_hash text UNIQUE NOT NULL, invited_by text, expires_at timestamptz NOT NULL, accepted_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE network_identities (id text PRIMARY KEY, family text NOT NULL CHECK (family='near'), environment text NOT NULL CHECK (environment IN ('test','live')), name text NOT NULL, enabled boolean NOT NULL DEFAULT false, settlement text NOT NULL DEFAULT 'final', config jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets (id text PRIMARY KEY, network_id text NOT NULL REFERENCES network_identities(id), address text NOT NULL, symbol text NOT NULL, name text NOT NULL, decimals integer NOT NULL CHECK(decimals BETWEEN 0 AND 30), peg_currency text NOT NULL DEFAULT 'USD', enabled boolean NOT NULL DEFAULT true, UNIQUE(network_id,address));
CREATE TABLE wallets (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL CHECK(environment IN ('test','live')), network_id text NOT NULL REFERENCES network_identities(id), name text NOT NULL, address text NOT NULL, monitoring_enabled boolean NOT NULL DEFAULT true, requested_backfill_from_block bigint, monitor_from_block bigint, created_by text, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,network_id,address));
CREATE TABLE wallet_assets (wallet_id text NOT NULL REFERENCES wallets(id), asset_id text NOT NULL REFERENCES assets(id), organization_id text NOT NULL REFERENCES organizations(id), PRIMARY KEY(wallet_id,asset_id));
CREATE TABLE customers (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL CHECK(environment IN ('test','live')), name text NOT NULL, email text, external_ref text, metadata jsonb NOT NULL DEFAULT '{}', archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_addresses (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, customer_id text NOT NULL REFERENCES customers(id), network_id text NOT NULL REFERENCES network_identities(id), address text NOT NULL, label text, source text NOT NULL DEFAULT 'manual', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,network_id,address));

CREATE TABLE order_sources (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, kind text NOT NULL, name text NOT NULL, secret_ciphertext text NOT NULL, secret_hint text, status text NOT NULL DEFAULT 'active', enabled boolean NOT NULL DEFAULT true, last_event_at timestamptz, created_by text, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoice_sequences (organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, next_value bigint NOT NULL DEFAULT 1, PRIMARY KEY(organization_id,environment));
CREATE TABLE invoices (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL CHECK(environment IN ('test','live')), customer_id text NOT NULL REFERENCES customers(id), number text NOT NULL, title text NOT NULL, purpose text, currency text NOT NULL DEFAULT 'USD', asset_id text NOT NULL REFERENCES assets(id), network_id text NOT NULL REFERENCES network_identities(id), wallet_id text NOT NULL REFERENCES wallets(id), amount_due numeric(78,0) NOT NULL CHECK(amount_due>0), amount_paid numeric(78,0) NOT NULL DEFAULT 0, amount_written_off numeric(78,0) NOT NULL DEFAULT 0, amount_credited numeric(78,0) NOT NULL DEFAULT 0, tax_amount numeric(78,0) NOT NULL DEFAULT 0, public_token text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'open', due_at timestamptz, issued_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, paid_at timestamptz, cancelled_at timestamptz, cancel_reason text, last_sent_at timestamptz, last_sent_to text, metadata jsonb NOT NULL DEFAULT '{}', created_by text, external_id text, order_source_id text REFERENCES order_sources(id), revenue_account_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,number), UNIQUE(organization_id,environment,order_source_id,external_id));
CREATE TABLE invoice_line_items (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), invoice_id text NOT NULL REFERENCES invoices(id), position integer NOT NULL, description text NOT NULL, quantity numeric(30,0) NOT NULL DEFAULT 1, unit_amount numeric(78,0) NOT NULL, amount numeric(78,0) NOT NULL, UNIQUE(invoice_id,position));
CREATE TABLE orders (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, source_id text REFERENCES order_sources(id), external_id text NOT NULL, customer_id text REFERENCES customers(id), invoice_id text REFERENCES invoices(id), status text NOT NULL DEFAULT 'received', payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,source_id,external_id));
CREATE TABLE order_source_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, source_id text REFERENCES order_sources(id), delivery_id text, topic text, external_id text, outcome text NOT NULL, detail text, invoice_id text REFERENCES invoices(id), received_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE source_observations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL CHECK(environment IN ('test','live')), source_type text NOT NULL CHECK(source_type IN ('nep141_transfer','simulated')), network_id text NOT NULL REFERENCES network_identities(id), block_number bigint NOT NULL, block_hash text NOT NULL, transaction_hash text NOT NULL, transaction_index integer NOT NULL DEFAULT 0, log_index integer NOT NULL DEFAULT 0, outcome_id text, transfer_index integer, token_address text NOT NULL, asset_id text REFERENCES assets(id), from_address text NOT NULL, to_address text NOT NULL, wallet_id text NOT NULL REFERENCES wallets(id), amount numeric(78,0) NOT NULL CHECK(amount>=0), block_timestamp timestamptz NOT NULL, confirmation_state text NOT NULL DEFAULT 'observed', canonical boolean NOT NULL DEFAULT true, finalized_at timestamptz, executed_at timestamptz, raw jsonb NOT NULL DEFAULT '{}', detection_source text NOT NULL DEFAULT 'rpc', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE NULLS NOT DISTINCT(organization_id,network_id,block_hash,transaction_hash,log_index,source_type,outcome_id,transfer_index));
CREATE TABLE observation_sightings (observation_id text NOT NULL REFERENCES source_observations(id), organization_id text NOT NULL REFERENCES organizations(id), source text NOT NULL, stage text NOT NULL, seen_at timestamptz NOT NULL DEFAULT now(), UNIQUE(observation_id,source,stage));
CREATE TABLE observation_state_changes (id bigserial PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), observation_id text NOT NULL REFERENCES source_observations(id), from_state text, to_state text NOT NULL, canonical boolean NOT NULL, reason text NOT NULL, head_block_number bigint, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL CHECK(environment IN ('test','live')), observation_id text NOT NULL UNIQUE REFERENCES source_observations(id), supporting_observation_id text REFERENCES source_observations(id), source text NOT NULL, wallet_id text NOT NULL REFERENCES wallets(id), network_id text NOT NULL REFERENCES network_identities(id), asset_id text REFERENCES assets(id), token_address text NOT NULL, amount numeric(78,0) NOT NULL, from_address text NOT NULL, to_address text NOT NULL, transaction_hash text NOT NULL, block_number bigint NOT NULL, block_timestamp timestamptz NOT NULL, status text NOT NULL DEFAULT 'confirming', invoice_id text REFERENCES invoices(id), provisional_invoice_id text REFERENCES invoices(id), customer_id text REFERENCES customers(id), latest_decision_id text, context_source text, finalized_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE match_decisions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, payment_id text NOT NULL REFERENCES payments(id), observation_id text NOT NULL REFERENCES source_observations(id), rule_version text NOT NULL, stage text NOT NULL, outcome text NOT NULL, exception_type text, invoice_id text REFERENCES invoices(id), customer_id text REFERENCES customers(id), checks jsonb NOT NULL DEFAULT '[]', candidates jsonb NOT NULL DEFAULT '[]', explanation text, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE payments ADD CONSTRAINT payments_latest_decision_fk FOREIGN KEY(latest_decision_id) REFERENCES match_decisions(id);
CREATE TABLE resolutions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, exception_id text, action text NOT NULL, reason text NOT NULL, invoice_id text REFERENCES invoices(id), actor_type text NOT NULL, actor_id text, actor_label text, previous_state jsonb NOT NULL DEFAULT '{}', new_state jsonb NOT NULL DEFAULT '{}', rule_version text NOT NULL, request_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_corrections (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, payment_id text NOT NULL REFERENCES payments(id), action text NOT NULL, from_invoice_id text NOT NULL REFERENCES invoices(id), to_invoice_id text REFERENCES invoices(id), reason text NOT NULL, actor_type text NOT NULL, actor_id text, actor_label text, previous_state jsonb NOT NULL, new_state jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE allocations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, payment_id text NOT NULL REFERENCES payments(id), invoice_id text NOT NULL REFERENCES invoices(id), amount numeric(78,0) NOT NULL, kind text NOT NULL, match_decision_id text REFERENCES match_decisions(id), resolution_id text REFERENCES resolutions(id), correction_id text REFERENCES payment_corrections(id), reverses_allocation_id text UNIQUE REFERENCES allocations(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exceptions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, type text NOT NULL, dedupe_key text NOT NULL, payment_id text NOT NULL REFERENCES payments(id), invoice_id text REFERENCES invoices(id), customer_id text REFERENCES customers(id), amount numeric(78,0) NOT NULL, asset_id text REFERENCES assets(id), network_id text NOT NULL REFERENCES network_identities(id), summary text NOT NULL, detail text NOT NULL, recommended_action text NOT NULL, candidates jsonb NOT NULL DEFAULT '[]', match_decision_id text REFERENCES match_decisions(id), status text NOT NULL DEFAULT 'open', resolution_id text REFERENCES resolutions(id), resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,dedupe_key));
ALTER TABLE resolutions ADD CONSTRAINT resolutions_exception_fk FOREIGN KEY(exception_id) REFERENCES exceptions(id);
CREATE TABLE credit_applications (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, customer_id text NOT NULL REFERENCES customers(id), payment_id text NOT NULL REFERENCES payments(id), from_invoice_id text NOT NULL REFERENCES invoices(id), to_invoice_id text NOT NULL REFERENCES invoices(id), asset_id text NOT NULL REFERENCES assets(id), amount numeric(78,0) NOT NULL, reverses_id text UNIQUE REFERENCES credit_applications(id), reason text, actor_type text NOT NULL, actor_id text, actor_label text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE network_cursors (network_id text PRIMARY KEY REFERENCES network_identities(id), next_block_number bigint NOT NULL, block_hash text, lease_owner text, lease_expires_at timestamptz, last_error text, last_error_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE webhook_endpoints (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, url text NOT NULL, description text, event_types text[] NOT NULL DEFAULT '{}', secret_ciphertext text NOT NULL, secret_hint text, previous_secret_ciphertext text, previous_secret_expires_at timestamptz, enabled boolean NOT NULL DEFAULT true, created_by text, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE financial_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, type text NOT NULL, event_version text NOT NULL DEFAULT '1', schema_version text NOT NULL DEFAULT '1.0', dedupe_key text NOT NULL, payment_id text REFERENCES payments(id), invoice_id text REFERENCES invoices(id), customer_id text REFERENCES customers(id), observation_id text REFERENCES source_observations(id), match_decision_id text REFERENCES match_decisions(id), resolution_id text REFERENCES resolutions(id), reverses_event_id text REFERENCES financial_events(id), amount numeric(78,0), asset_id text REFERENCES assets(id), network_id text REFERENCES network_identities(id), rule_version text NOT NULL, data jsonb NOT NULL, occurred_at timestamptz NOT NULL, journal_entry_id text, vendor_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,dedupe_key));
CREATE TABLE webhook_deliveries (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, endpoint_id text NOT NULL REFERENCES webhook_endpoints(id), event_id text REFERENCES financial_events(id), event_type text NOT NULL, payload jsonb NOT NULL, status webhook_delivery_status NOT NULL DEFAULT 'pending', attempt_count integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, last_response_status integer, last_error text, delivered_at timestamptz, replay_of text REFERENCES webhook_deliveries(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX webhook_deliveries_original_event_unique ON webhook_deliveries(endpoint_id,event_id) WHERE replay_of IS NULL AND event_id IS NOT NULL;
CREATE TABLE webhook_attempts (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), delivery_id text NOT NULL REFERENCES webhook_deliveries(id), attempt_number integer NOT NULL, request_url text NOT NULL, request_headers jsonb NOT NULL, response_status integer, response_headers jsonb, response_body_excerpt text, error text, duration_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(delivery_id,attempt_number));

CREATE TABLE accounting_settings (organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, method text NOT NULL DEFAULT 'accrual', reporting_currency text NOT NULL DEFAULT 'USD', books_initialized_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,environment));
CREATE TABLE accounting_issues (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, source_key text NOT NULL, source_type text NOT NULL, source_id text, message text NOT NULL, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,source_key));
CREATE TABLE ledger_accounts (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, code text NOT NULL, name text NOT NULL, type text NOT NULL, subtype text, normal_balance text NOT NULL, description text, system_key text, wallet_id text REFERENCES wallets(id), asset_id text REFERENCES assets(id), native_symbol text, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,code));
CREATE UNIQUE INDEX ledger_accounts_system_key_unique ON ledger_accounts(organization_id,environment,system_key) WHERE system_key IS NOT NULL;
CREATE UNIQUE INDEX ledger_accounts_wallet_asset_unique ON ledger_accounts(organization_id,environment,wallet_id,asset_id) WHERE wallet_id IS NOT NULL AND asset_id IS NOT NULL;
CREATE UNIQUE INDEX ledger_accounts_wallet_native_unique ON ledger_accounts(organization_id,environment,wallet_id,native_symbol) WHERE wallet_id IS NOT NULL AND native_symbol IS NOT NULL;
ALTER TABLE invoices ADD CONSTRAINT invoices_revenue_account_fk FOREIGN KEY(revenue_account_id) REFERENCES ledger_accounts(id);
CREATE TABLE journal_sequences (organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, next_value bigint NOT NULL DEFAULT 1, PRIMARY KEY(organization_id,environment));
CREATE TABLE accounting_periods (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, status text NOT NULL DEFAULT 'open', closed_at timestamptz, closed_by text, closed_by_label text, reopened_at timestamptz, reopen_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,start_date));
CREATE TABLE journal_entries (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, number text NOT NULL, entry_date date NOT NULL, description text NOT NULL, memo text, source_type text NOT NULL, source_id text, source_key text, currency text NOT NULL DEFAULT 'USD', status text NOT NULL DEFAULT 'draft', reverses_entry_id text REFERENCES journal_entries(id), original_date date, created_by_type text, created_by_id text, created_by_label text, request_id text, approved_at timestamptz, approved_by_id text, approved_by_label text, posted_at timestamptz, posted_by_id text, posted_by_label text, voided_at timestamptz, void_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,number), UNIQUE(organization_id,environment,source_key));
CREATE TABLE vendors (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, name text NOT NULL, email text, external_ref text, default_account_id text REFERENCES ledger_accounts(id), notes text, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendor_addresses (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, vendor_id text NOT NULL REFERENCES vendors(id), network_id text NOT NULL REFERENCES network_identities(id), address text NOT NULL, label text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,network_id,address));
CREATE TABLE recurring_bills (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, vendor_id text NOT NULL REFERENCES vendors(id), title text NOT NULL, amount numeric(78,0) NOT NULL, account_id text NOT NULL REFERENCES ledger_accounts(id), frequency text NOT NULL, anchor_day integer, next_date date NOT NULL, end_date date, due_days integer NOT NULL DEFAULT 0, auto_approve boolean NOT NULL DEFAULT false, number_prefix text, status text NOT NULL DEFAULT 'active', bills_created integer NOT NULL DEFAULT 0, last_bill_date date, created_by_label text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bills (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, vendor_id text NOT NULL REFERENCES vendors(id), number text NOT NULL, title text NOT NULL, description text, amount numeric(78,0) NOT NULL, amount_paid numeric(78,0) NOT NULL DEFAULT 0, account_id text NOT NULL REFERENCES ledger_accounts(id), bill_date date NOT NULL, due_date date, status text NOT NULL DEFAULT 'draft', recurring_bill_id text REFERENCES recurring_bills(id), created_by_id text, approved_at timestamptz, approved_by_id text, approved_by_label text, voided_at timestamptz, void_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,vendor_id,number));
CREATE TABLE expenses (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, vendor_id text REFERENCES vendors(id), title text NOT NULL, description text, amount numeric(78,0) NOT NULL, account_id text NOT NULL REFERENCES ledger_accounts(id), expense_date date NOT NULL, reference text, method text NOT NULL DEFAULT 'offchain', paid_from_account_id text NOT NULL REFERENCES ledger_accounts(id), notes text, status text NOT NULL DEFAULT 'pending', rejected_reason text, created_by_id text, created_by_label text, approved_at timestamptz, approved_by_id text, approved_by_label text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE journal_lines (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, entry_id text NOT NULL REFERENCES journal_entries(id), position integer NOT NULL, account_id text NOT NULL REFERENCES ledger_accounts(id), debit numeric(78,0) NOT NULL DEFAULT 0, credit numeric(78,0) NOT NULL DEFAULT 0, memo text, customer_id text REFERENCES customers(id), vendor_id text REFERENCES vendors(id), invoice_id text REFERENCES invoices(id), bill_id text REFERENCES bills(id), expense_id text REFERENCES expenses(id), payment_id text REFERENCES payments(id), observation_id text REFERENCES source_observations(id), financial_event_id text REFERENCES financial_events(id), asset_id text REFERENCES assets(id), asset_amount numeric(78,0), rate_source text, UNIQUE(entry_id,position), CHECK(debit>=0 AND credit>=0 AND NOT(debit>0 AND credit>0)));
ALTER TABLE financial_events ADD CONSTRAINT financial_events_journal_fk FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id);
CREATE TABLE bill_payments (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, bill_id text NOT NULL REFERENCES bills(id), amount numeric(78,0) NOT NULL, method text NOT NULL, paid_from_account_id text NOT NULL REFERENCES ledger_accounts(id), paid_on date NOT NULL, reference text, memo text, actor_type text, actor_id text, actor_label text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE transaction_classifications (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, kind text NOT NULL, payment_id text NOT NULL REFERENCES payments(id), account_id text NOT NULL REFERENCES ledger_accounts(id), reason text NOT NULL, actor_type text, actor_id text, actor_label text, reversed_at timestamptz, reversed_by_label text, reversal_reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_notes (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, invoice_id text NOT NULL REFERENCES invoices(id), customer_id text NOT NULL REFERENCES customers(id), number text NOT NULL, amount numeric(78,0) NOT NULL, reason text NOT NULL, account_id text NOT NULL REFERENCES ledger_accounts(id), actor_type text, actor_id text, actor_label text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fx_rates (id text PRIMARY KEY, organization_id text REFERENCES organizations(id), base text NOT NULL, quote text NOT NULL, rate_date date NOT NULL, rate numeric NOT NULL, source text NOT NULL, note text, created_by_label text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE NULLS NOT DISTINCT(organization_id,base,quote,rate_date));
CREATE TABLE bank_statement_imports (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, account_id text NOT NULL REFERENCES ledger_accounts(id), filename text, line_count integer NOT NULL DEFAULT 0, skipped_count integer NOT NULL DEFAULT 0, created_by_label text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bank_statement_lines (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, account_id text NOT NULL REFERENCES ledger_accounts(id), import_id text NOT NULL REFERENCES bank_statement_imports(id), line_date date NOT NULL, description text NOT NULL, reference text, amount numeric(78,0) NOT NULL, fingerprint text NOT NULL, status text NOT NULL DEFAULT 'unmatched', journal_line_id text REFERENCES journal_lines(id), matched_at timestamptz, matched_by_label text, excluded_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,environment,account_id,fingerprint));
CREATE TABLE bank_reconciliations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, account_id text NOT NULL REFERENCES ledger_accounts(id), statement_date date NOT NULL, statement_balance numeric(78,0) NOT NULL, ledger_balance numeric(78,0) NOT NULL, uncleared_total numeric(78,0) NOT NULL, completed_by_label text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachments (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, object_type text NOT NULL, object_id text NOT NULL, filename text NOT NULL, content_type text NOT NULL, size_bytes integer NOT NULL, sha256 text NOT NULL, data bytea NOT NULL, uploaded_by_label text, removed_at timestamptz, removed_by_label text, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE audit_logs (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text, actor_type text NOT NULL, actor_id text, actor_label text, action text NOT NULL, object_type text NOT NULL, object_id text NOT NULL, previous_state jsonb, new_state jsonb, request_id text, ip_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, name text NOT NULL, prefix text NOT NULL, secret_hash text UNIQUE NOT NULL, scope text NOT NULL, created_by text, last_used_at timestamptz, revoked_at timestamptz, revoked_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, key text NOT NULL, request_fingerprint text NOT NULL, state text NOT NULL DEFAULT 'processing', response_status integer, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now() + interval '24 hours', PRIMARY KEY(organization_id,environment,key));
CREATE TABLE assistant_conversations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, user_id text, title text, pending jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assistant_messages (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), conversation_id text NOT NULL REFERENCES assistant_conversations(id), role text NOT NULL, text text NOT NULL DEFAULT '', intent text, blocks jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assistant_actions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), environment text NOT NULL, conversation_id text REFERENCES assistant_conversations(id), user_id text, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', expires_at timestamptz NOT NULL, resolved_at timestamptz, result jsonb, created_at timestamptz NOT NULL DEFAULT now());

-- Evidence and economic history are append-only. Corrections use compensating records.
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION '% is append-only and cannot be deleted', TG_TABLE_NAME; END IF;
  RAISE EXCEPTION '% is append-only and cannot be changed', TG_TABLE_NAME;
END $$;
CREATE FUNCTION guard_observation_evidence() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.organization_id<>OLD.organization_id OR NEW.environment<>OLD.environment OR NEW.source_type<>OLD.source_type OR NEW.network_id<>OLD.network_id OR
     NEW.block_number<>OLD.block_number OR NEW.block_hash<>OLD.block_hash OR NEW.transaction_hash<>OLD.transaction_hash OR
     NEW.transaction_index<>OLD.transaction_index OR NEW.log_index<>OLD.log_index OR NEW.token_address<>OLD.token_address OR
     NEW.from_address<>OLD.from_address OR NEW.to_address<>OLD.to_address OR NEW.wallet_id<>OLD.wallet_id OR
     NEW.amount<>OLD.amount OR NEW.block_timestamp<>OLD.block_timestamp OR NEW.raw<>OLD.raw
  THEN RAISE EXCEPTION 'source observation evidence is immutable'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER source_observation_evidence_guard BEFORE UPDATE ON source_observations FOR EACH ROW EXECUTE FUNCTION guard_observation_evidence();
CREATE TRIGGER source_observation_no_delete BEFORE DELETE ON source_observations FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER financial_events_append_only BEFORE UPDATE OR DELETE ON financial_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER allocations_append_only BEFORE UPDATE OR DELETE ON allocations FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER audit_logs_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION guard_resolution_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.new_state='{}'::jsonb AND NEW.new_state<>OLD.new_state AND (to_jsonb(NEW)-'new_state')=(to_jsonb(OLD)-'new_state') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'resolutions are append-only';
END $$;
CREATE TRIGGER resolutions_append_only BEFORE UPDATE ON resolutions FOR EACH ROW EXECUTE FUNCTION guard_resolution_update();
CREATE TRIGGER resolutions_no_delete BEFORE DELETE ON resolutions FOR EACH ROW EXECUTE FUNCTION reject_mutation();

-- Requests set app.organization_id; cross-tenant workers explicitly set app.system=on.
CREATE FUNCTION tenant_visible(row_org text) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT current_setting('app.system',true)='on' OR row_org=nullif(current_setting('app.organization_id',true),'')
$$;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'organization_members','invitations','wallets','wallet_assets','customers','customer_addresses','order_sources','invoice_sequences','invoices','invoice_line_items','orders','order_source_events',
    'source_observations','observation_sightings','observation_state_changes','payments','match_decisions','allocations','exceptions','resolutions','payment_corrections','credit_applications',
    'webhook_endpoints','financial_events','webhook_deliveries','webhook_attempts','accounting_settings','accounting_issues','ledger_accounts','journal_sequences','accounting_periods','journal_entries',
    'vendors','vendor_addresses','recurring_bills','bills','expenses','journal_lines','bill_payments','transaction_classifications','credit_notes','bank_statement_imports','bank_statement_lines','bank_reconciliations','attachments',
    'audit_logs','api_keys','idempotency_keys','assistant_conversations','assistant_messages','assistant_actions'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
    EXECUTE format('CREATE POLICY tenant_policy ON %I USING (tenant_visible(organization_id)) WITH CHECK (tenant_visible(organization_id))',t);
  END LOOP;
END $$;

DO $$ BEGIN
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='zetra_app') THEN
    GRANT USAGE ON SCHEMA public TO zetra_app;
    GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO zetra_app;
    GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO zetra_app;
  END IF;
END $$;

CREATE INDEX payments_org_status_time ON payments(organization_id,environment,status,block_timestamp DESC);
CREATE INDEX invoices_org_status ON invoices(organization_id,environment,status);
CREATE INDEX observations_wallet_block ON source_observations(wallet_id,block_number);
CREATE INDEX exceptions_org_status ON exceptions(organization_id,environment,status);
CREATE INDEX journal_lines_entry ON journal_lines(entry_id);
CREATE INDEX journal_entries_org_date ON journal_entries(organization_id,environment,entry_date);
